%[text] # Motor Drive Unit - Simulation Case
%[text] ## Driving motor
%[text] Test that the motor can drive the axle. Stress-test check points
%[text] 1. Simulation must work regardless of the rotational direction.
%[text] 2. A sudden change in the rotational direction must be handled reasonably.   \
model_name = "HarnessModel_MotorDriveUnit";
load_system(model_name)

setupHarness_MotorDriveUnit

set_param(model_name + "/Motor Drive Unit", ReferencedSubsystem = "MotorDriveUnit_BasicThermal_refsub")

set_param(model_name + "/Inputs", ReferencedSubsystem = "Inputs_MotorDriveUnit_Drive_refsub")

% Initial conditions
initial.LoadInertiaSpeed = simscape.Value(0, "rpm");
initial.motorDriveUnit_RotorSpd_rpm = 0;
initial.ambientTemp_K = motorDriveUnit.ambientTemp_K;

sim_in = Simulink.SimulationInput(model_name);
sim_in = setModelParameter(sim_in, StopTime = "400");
%[text] Run simulation.
sim_out = sim(sim_in);
%[text] Visually inspect the result.
sim_data = extractTimetable(sim_out.logsout);

% Signal logging names in the model.
signal_names = [
  "Motor torque command"
  "Axle torque input"
  "Motor power rate"
  "Motor speed"
  "Motor temperature"
  "Battery power"
  "Battery current"
  "Battery voltage"
  ];

for idx = 1 : numel(signal_names) %[output:group:423024c8]
  fig = bevutil1.SignalUtil.plotTimedData(TimedData = sim_data, SignalName = signal_names(idx)); %[output:5450524f] %[output:96cb174d] %[output:28bde25b] %[output:0d688e92] %[output:16fe85b1] %[output:93786cb3] %[output:692f6312] %[output:1f2ed25f]
  fig.Position(4) = 200;  % height
end %[output:group:423024c8]
